<?php
namespace Modules\Analytics\Controllers\Web;
use Core\http\ResponseFactory;use Modules\Analytics\Services\AdminSettingService;use RuntimeException;
class AdminSettingController{public function __construct(private AdminSettingService$s){}public function show(){return ResponseFactory::json(['success'=>true,'data'=>$this->s->get()]);}public function save(){try{$d=$this->payload();return ResponseFactory::json(['success'=>true,'data'=>$this->s->save((int)auth()->id(),$d)]);}catch(\Throwable$e){return ResponseFactory::json(['success'=>false,'message'=>$e->getMessage()],422);}}private function payload():array{$raw=base64_decode(strtr((string)request()->input('payload_b64',''),'-_','+/'),true);$d=$raw===false?null:json_decode($raw,true);if(!is_array($d))throw new RuntimeException('تنظیمات معتبر نیست.');return$d;}}
